.text-box{
  width 100%;
  background #fff;
  padding 8px 5px 8px 12px;
  font-size 15px;
  color #333;
  border-bottom 1px solid #eee;
  align-items baseline;
  .title{
    width 95px;
  }
  .textVal{
    width 250px;
    .item{
      font-size: 13px;
      color: #282828;
      padding 5px 0;
      margin 0 10px;
      .select{
        width: 17px;
        height: 17px;
        border: 1px solid #CCCCCC;
        margin-right 7px;
        .iconfont{
          font-size 12px;
        }
        &.on{
          background-color #E93323;
          color #fff;
          border-color #e93323;
        }
      }
    }
  }
}
